const items = $input.all();

await new Promise((resolve) => setTimeout(resolve, 15_000));

return items;

// LEVEL 1: Extract investment/listing URLs from NO search page
const items = $input.all();

function extractHtml(item) {
	if (item.binary?.data?.data) {
		return Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
	}
	if (typeof item === 'string') {
		return item;
	}
	if (typeof item?.json === 'string') {
		return item.json;
	}
	if (item?.json?.data) {
		return item.json.data;
	}
	if (item?.data) {
		return item.data;
	}
	return JSON.stringify(item?.json || item || '');
}

function cleanText(value) {
	if (!value) return '';
	return String(value)
		.replace(/<[^>]+>/g, ' ')
		.replace(/&nbsp;|&#160;/g, ' ')
		.replace(/&amp;/g, '&')
		.replace(/&quot;/g, '"')
		.replace(/&#39;|&apos;/g, "'")
		.replace(/&sup2;/g, '²')
		.replace(/\s+/g, ' ')
		.trim();
}

function toAbsoluteUrl(rawUrl) {
	const value = String(rawUrl || '').trim();
	if (!value) return '';
	const absolute = value.startsWith('http')
		? value
		: `https://krakow.nieruchomosci-online.pl${value.startsWith('/') ? '' : '/'}${value}`;
	return absolute.split('?')[0].trim();
}

function isInvestmentUrl(url) {
	if (!url.includes('nieruchomosci-online.pl')) return false;
	if (!/\.html$/i.test(url)) return false;
	if (/\/szukaj\.html$/i.test(url)) return false;
	if (/\/(\d{7,10})\.html$/i.test(url)) return false;
	if (/\/dodaj\.html$/i.test(url)) return false;
	if (/\/oferta-dla-/i.test(url)) return false;
	return true;
}

function parseFromHrefFallback(html) {
	const results = [];
	const regex = /href="([^"]+\.html(?:\?[^\"]*)?)"/g;
	let match;

	while ((match = regex.exec(html)) !== null) {
		const url = toAbsoluteUrl(match[1]);
		if (!url || !isInvestmentUrl(url)) continue;

		const slug = (url.match(/\/([^\/]+)\.html$/i) || [])[1] || '';
		results.push({
			url,
			investment_name: cleanText(slug.replace(/-/g, ' ')),
			investment_id: slug,
		});
	}

	return results;
}

try {
	const allResults = [];

	for (const item of items) {
		const html = extractHtml(item);
		allResults.push(...parseFromHrefFallback(html));
	}

	const uniqueMap = new Map();
	for (const entry of allResults) {
		if (entry?.url) {
			uniqueMap.set(entry.url, entry);
		}
	}

	return Array.from(uniqueMap.values()).map((json) => ({ json }));
} catch (error) {
	return [{ json: { error: `Level 1 parsing error: ${error.message}` } }];
}

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '').slice(0, 15) + 'Z';
const random = Math.random().toString(36).slice(2, 14).toUpperCase();

return [{
  json: {
    run_id: `${timestamp}__${random}`,
    workflow_name: 'Real Estate AI Agent',
    workflow_version: '1.8.1',
    trigger_source: 'schedule',
    started_at: now.toISOString(),
  }
}];

const crypto = require('crypto');
const items = $input.all();
const run = $node['tlm-init-run']?.json || {};
const runId = String(run.run_id || '').trim() || null;
function classifyOffer(offer) { return { ...offer, geo_status: 'unknown', geo_confidence: 'low', geo_reason: 'Krakow detected but district is missing or unsupported.', policy_version: 'south-krakow-v1', is_exception_candidate: false, review_status: 'pending', is_soft_blocked: true, needs_manual_review: true, excluded_from_feedback_loop: true, is_in_trash: false }; }
function extractHtml(item) { if (item.binary && item.binary.data) return Buffer.from(item.binary.data.data, 'base64').toString('utf-8'); if (typeof item === 'string') return item; if (item && item.data) return item.data; if (typeof item.json === 'string') return item.json; if (item.json && item.json.data) return item.json.data; return JSON.stringify(item.json || item); }
function cleanText(value) { if (!value) return ''; return String(value).replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&sup2;/g, '²').replace(/\s+/g, ' ').trim(); }
function toNumber(value) { if (typeof value === 'number') return Number.isFinite(value) ? value : 0; if (value === null || value === undefined || value === '') return 0; const normalized = String(value).replace(/\u00a0/g, '').replace(/\s+/g, '').replace(',', '.').replace(/[^\d.-]/g, ''); const parsed = Number(normalized); return Number.isFinite(parsed) ? parsed : 0; }
function parseAreaFromText(value) { const text = cleanText(value); const match = text.match(/([\d.,]+)\s*m(?:²|2)/i); return match ? toNumber(match[1]) : 0; }
function stripQuery(url) { return String(url || '').split('?')[0].trim(); }
function normalizeNoHost(url) { const raw = String(url || '').trim(); if (!raw) return ''; return raw.replace(/^https?:\/\/krakow\.nieruchomosci-online\.pl/i, 'https://www.nieruchomosci-online.pl'); }
function findOffers(node, out) { if (!node) return; if (Array.isArray(node)) { node.forEach((entry) => findOffers(entry, out)); return; } if (typeof node !== 'object') return; if (node['@type'] === 'Offer') out.push(node); Object.values(node).forEach((value) => findOffers(value, out)); }
function parseJsonLdOffers(html) { const blocks = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)]; const offers = []; for (const block of blocks) { try { const parsed = JSON.parse((block[1] || '').trim()); findOffers(parsed, offers); } catch (error) {} } return offers; }
function collectDebugStats(html, offersCount) { const normalized = String(html || ''); const lower = normalized.toLowerCase(); const is404 = lower.includes('strona błędu 404') || lower.includes('strona bledu 404') || lower.includes('ups... chyba ktos glodny zjadl te strone') || lower.includes('ups... chyba ktoś głodny zjadł tę stronę'); const jsonLdBlocks = [...normalized.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>/gi)].length; const concreteOfferLinks = [...normalized.matchAll(/\/\d{7,10}\.html/gi)].length; return { is_404: is404, jsonld_blocks: jsonLdBlocks, jsonld_offer_nodes: offersCount, concrete_offer_links: concreteOfferLinks, html_length: normalized.length }; }
function buildExternalId(url, index) { const idMatch = String(url).match(/\/(\d{7,10})\.html/i); if (idMatch) return `NO-${idMatch[1]}`; if (url) return `NO-${crypto.createHash('md5').update(url).digest('hex')}`; return `NO-${index + 1}`; }
try { const results = []; const diagnostics = []; for (const item of items) { const html = extractHtml(item); const offers = parseJsonLdOffers(html); diagnostics.push(collectDebugStats(html, offers.length)); for (let index = 0; index < offers.length; index += 1) { const offer = offers[index] || {}; const rawUrl = normalizeNoHost(stripQuery(offer.url || '')); if (!/\/(\d{7,10})\.html/i.test(rawUrl)) continue; const title = cleanText(offer.name || (offer.itemOffered && offer.itemOffered.name)); const area = toNumber(offer.itemOffered && offer.itemOffered.floorSize && (offer.itemOffered.floorSize.value || offer.itemOffered.floorSize)) || parseAreaFromText(title); const pricePerM2 = toNumber(offer.priceSpecification && offer.priceSpecification.price) || (area > 0 ? Math.round((toNumber(offer.price) / area) * 100) / 100 : 0); results.push(classifyOffer({ external_id: buildExternalId(rawUrl, index), url: rawUrl, category: 'mieszkanie-krakow', title: title || `Oferta NO: ${index + 1}`, price: toNumber(offer.price), price_per_m2: pricePerM2, area, lot_size: 0, construction_year: 0, created_at: new Date().toISOString(), property_portal: 'Nieruchomości online', location_text: 'Kraków', district: 'Kraków', market_type: 'residential', source_offer_id: '', portal_source: 'no', run_id: runId })); } } const uniqueMap = new Map(); results.forEach((result) => uniqueMap.set(result.external_id, result)); const uniqueResults = Array.from(uniqueMap.values()); if (uniqueResults.length === 0) { return []; } const mainItems = uniqueResults.map((json) => ({ json })); return mainItems; } catch (error) { return []; }

return [{
  json: {
    "workflow_name": "Real Estate AI Agent",
    "workflow_version": "1.8.1",
    "workflow_display_name": "Real Estate AI Agent",
    "git_sha": "unknown",
