  }
}];

const allHtmlInputs = $input.all();
const allOffersFromSql = $("sql-backfill-ai").all();

function decodeHtmlEntities(text) {
  return String(text || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function htmlToAiText(html) {
  const source = String(html || '');
  if (!source) return '';

  let text = source
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<\/(p|div|li|h1|h2|h3|h4|h5|h6|tr|section|article|br)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');

  text = decodeHtmlEntities(text)
    .replace(/\r/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

  const MAX_CHARS = 24000;
  if (text.length > MAX_CHARS) {
    text = text.slice(0, MAX_CHARS) + '\n\n[TRUNCATED_FOR_TOKEN_LIMIT]';
  }

  return text;
}

return allHtmlInputs.map((htmlItem, index) => ({
  json: {
    ...(allOffersFromSql[index] ? allOffersFromSql[index].json : {}),
    raw_md: htmlToAiText(htmlItem.json.data || 'No content'),
    ai_input_md: htmlToAiText(htmlItem.json.data || 'No content')
  }
}));

