function getStatusCode(item) {
  return Number(item.json.statusCode ?? item.json.status ?? item.json.httpCode ?? 0);
}

function getHtmlBody(item) {
  return String(item.json.body ?? item.json.data ?? '').trim();
}

const mergedItems = [];

for (let index = 0; index < responses.length; index += 1) {
  const responseItem = responses[index];
  const sourceItem = sourceOffers[index]?.json;

  if (!sourceItem) {
    continue;
  }

  const statusCode = getStatusCode(responseItem);
  if (statusCode >= 400) {
    continue;
  }

  const html = getHtmlBody(responseItem);
  if (!html) {
    continue;
  }

  mergedItems.push({
    json: {
      ...sourceItem,
      raw_md: htmlToAiText(html),
      ai_input_md: htmlToAiText(html),
      fetch_status_code: statusCode || null,
    },
  });
}

return mergedItems;

