const run = $node['tlm-init-run']?.json || {};
const runId = String(run.run_id || '').trim() || null;
const html = items[0]?.json?.data || '';
if (!html) return [];
const jsonMatch = html.match(/<script\b[^>]*type="application\/json"[^>]*>([\s\S]*?pageProps[\s\S]*?)<\/script>/);
if (!jsonMatch) return [];
try { const fullData = JSON.parse(jsonMatch[1].trim()); const ads = fullData?.props?.pageProps?.data?.searchAds?.items || fullData?.props?.pageProps?.apolloState?.data?.searchAds?.items || []; const offers = ads.map((ad) => ({ json: { external_id: 'OT-' + ad.id, category: 'mieszkanie-krakow', url: 'https://www.otodom.pl/pl/oferta/' + ad.slug, title: 'Oferta OT: ' + ad.title, price: ad.totalPrice?.value || 0, price_per_m2: ad.pricePerSquareMeter?.value || 0, area: ad.areaInSquareMeters || 0, rooms: ad.roomsNumber || 0, lot_size: 0, construction_year: 0, created_at: new Date().toISOString(), property_portal: 'Otodom', portal_source: 'otodom', run_id: runId } })); return offers; } catch (error) { return []; }

const items = $input.all();

const normalizePortal = (value) => {
  const portal = String(value || '').trim().toLowerCase();
  if (portal === 'nieruchomości online' || portal === 'nieruchomosci online' || portal === 'no') return 'no';
  if (portal === 'otodom') return 'otodom';
  return portal || 'unknown';
};

return items
  .filter((item) => item.json?.external_id && item.json?.url)
  .map((item) => ({
    json: {
      run_id: item.json.run_id,
      stage_key: 'parse_list',
      stage_order: 1,
