      },
    },
  }));

const items = $input.all();
const sourceOffers = $('tlm-attach-run-id').all();

function mapReason(responseItem) {
  const explicitStatus = Number(responseItem.json.statusCode ?? responseItem.json.status ?? responseItem.json.httpCode ?? 0);
  const errorMessage = String(responseItem.json.error || responseItem.json.message || '').toLowerCase();

  if (explicitStatus === 404) return 'http_404';
  if (explicitStatus === 403) return 'http_403';
  if (errorMessage.includes('timeout') || explicitStatus === 408 || explicitStatus === 504) return 'http_timeout';
  if (explicitStatus >= 400) return 'http_other';

  const html = String(responseItem.json.body ?? responseItem.json.data ?? '').trim();
  if (!html) return 'http_other';

  return null;
}

return items.map((responseItem, index) => {
