  if (item.json.event_type === 'passed') {
    passed += 1;
    continue;
  }

  if (item.json.event_type === 'dropped') {
    dropped += 1;
    errorCount += 1;
    const reason = String(item.json.event_reason || 'http_other');
    dropsByReason[reason] = (dropsByReason[reason] || 0) + 1;
  }
}

return [
