const inferConstructionYearFromHtml = (html) => {
  const source = String(html || '');
  if (!source) return null;

  const patterns = [
    /Rok\s+budowy[^0-9]{0,20}(20\d{2}|19\d{2})/i,
    /"Rok\s+budowy"\s*,\s*"value"\s*:\s*"(20\d{2}|19\d{2})"/i,
    /built[^0-9]{0,20}(20\d{2}|19\d{2})/i,
