const inferLotSizeFromRaw = (text) => inferNumericFieldFromRaw(text, 'lot_size');
const inferConstructionYearFromRaw = (text) => inferNumericFieldFromRaw(text, 'construction_year') ?? inferNumericFieldFromRaw(text, 'year');

const inferAiAnalysisHtmlFromRaw = (text) => {
  const source = stripFences(text);
  const marker = '"ai_analysis_html"';
  const markerIndex = source.toLowerCase().indexOf(marker.toLowerCase());
  if (markerIndex === -1) return '';

  const afterMarker = source.slice(markerIndex);
  const firstQuote = afterMarker.indexOf('"', marker.length);
  if (firstQuote === -1) return '';

  const valuePart = afterMarker.slice(firstQuote + 1);
  const endQuoteMatch = valuePart.match(/"\s*(,|\})/);
  const quoted = endQuoteMatch ? valuePart.slice(0, endQuoteMatch.index) : valuePart;

  const normalized = quoted
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\"/g, '"')
    .replace(/\\\//g, '/');

  return String(normalized || '').trim();
};

const buildCurrentParsed = () => {
  const currentAiRating = parseNullableNumber($json.ai_rating);
  const rawExternalId = inferExternalIdFromRaw(raw);

  return {
    external_id: String($json.external_id || rawExternalId || '').trim(),
    title: String($json.title || inferTitleFromRaw(raw) || '').trim(),
    price: inferPriceFromRaw(raw) ?? parseNumber($json.price, 0),
    price_per_m2: inferPricePerM2FromRaw(raw) ?? parseNumber($json.price_per_m2, 0),
    area: inferAreaFromRaw(raw) ?? parseNumber($json.area, 0),
    lot_size: inferLotSizeFromRaw(raw) ?? parseNumber($json.lot_size, 0),
    construction_year: Math.round(inferConstructionYearFromRaw(raw) ?? parseNumber($json.construction_year, 0)),
    ai_rating: currentAiRating === null ? (Number.isFinite(inferAiRatingFromRaw(raw)) ? Math.round(inferAiRatingFromRaw(raw)) : null) : Math.round(currentAiRating),
    ai_analysis_html: String($json.ai_analysis_html || inferAiAnalysisHtmlFromRaw(raw) || '').trim(),
  };
};

const buildFailure = (reason, details = {}) => ([{
  json: {
    ...$json,
    ai_parse_valid: false,
    ai_parse_error: reason,
    ai_parse_details: details,
    ai_parsed: buildCurrentParsed(),
  },
}]);

if (!raw) {
  return buildFailure('empty_output');
}

const parseJson = (text) => {
  const candidate = stripFences(text);

  try {
    return JSON.parse(candidate);
  } catch (_) {
    const objectMatch = candidate.match(/\{[\s\S]*\}/);
    if (!objectMatch) return null;

    try {
      return JSON.parse(objectMatch[0]);
    } catch (_) {
      return null;
    }
  }
};

const expectedExternalId = String($json.external_id || '').trim();
const parsed = parseJson(raw);

let parsedExternalId = '';
let parsedTitle = '';
let parsedPrice = parseNumber($json.price, 0);
let parsedPricePerM2 = parseNumber($json.price_per_m2, 0);
let parsedArea = parseNumber($json.area, 0);
let parsedLotSize = parseNumber($json.lot_size, 0);
let parsedConstructionYear = Math.round(parseNumber($json.construction_year, 0));
let aiRating = parseNullableNumber($json.ai_rating);
let aiAnalysisHtml = String($json.ai_analysis_html || '').trim();
let parseError = null;
let parseDetails = null;

if (parsed && typeof parsed === 'object') {
  parsedExternalId = String(parsed.external_id || '').trim();
  parsedTitle = String(parsed.title || '').trim();
  parsedPrice = parseNumber(parsed.price, parsedPrice);
  parsedPricePerM2 = parseNumber(parsed.price_per_m2, parsedPricePerM2);
  parsedArea = parseNumber(parsed.area, parsedArea);
  parsedLotSize = parseNumber(parsed.lot_size, parsedLotSize);
  parsedConstructionYear = Math.round(parseNumber(parsed.construction_year, parsedConstructionYear));
  aiRating = parseNullableNumber(parsed.ai_rating);
  aiAnalysisHtml = String(parsed.ai_analysis_html || aiAnalysisHtml).trim();
} else {
  parsedExternalId = inferExternalIdFromRaw(raw);
  parsedTitle = inferTitleFromRaw(raw) || String($json.title || '').trim();
  parsedPrice = inferPriceFromRaw(raw) ?? parsedPrice;
  parsedPricePerM2 = inferPricePerM2FromRaw(raw) ?? parsedPricePerM2;
  parsedArea = inferAreaFromRaw(raw) ?? parsedArea;
  parsedLotSize = inferLotSizeFromRaw(raw) ?? parsedLotSize;
  parsedConstructionYear = Math.round(inferConstructionYearFromRaw(raw) ?? parsedConstructionYear);
  const recoveredRating = inferAiRatingFromRaw(raw);
  aiRating = Number.isFinite(recoveredRating) ? recoveredRating : aiRating;
  aiAnalysisHtml = inferAiAnalysisHtmlFromRaw(raw) || aiAnalysisHtml;

  parseError = 'invalid_json_recovered';
  parseDetails = {
    recovered_external_id: parsedExternalId || null,
    recovered_title: parsedTitle || null,
    recovered_price: parsedPrice || null,
    recovered_price_per_m2: parsedPricePerM2 || null,
    recovered_area: parsedArea || null,
    recovered_lot_size: parsedLotSize || null,
    recovered_construction_year: parsedConstructionYear || null,
    recovered_ai_rating: Number.isFinite(aiRating) ? aiRating : null,
  };
}

if (!parsedExternalId) {
  parsedExternalId = expectedExternalId;
}

if (!parsedExternalId) {
  return buildFailure('missing_external_id');
}

if (expectedExternalId && parsedExternalId !== expectedExternalId) {
  return buildFailure('external_id_mismatch', {
    expected_external_id: expectedExternalId,
    parsed_external_id: parsedExternalId,
  });
}

const roundedRating = aiRating === null ? null : Math.round(parseNumber(aiRating, NaN));
if (!Number.isFinite(roundedRating) || roundedRating < 1 || roundedRating > 10) {
  return buildFailure('invalid_ai_rating', {
    parsed_ai_rating: aiRating,
  });
}

if (!aiAnalysisHtml) {
  const fallbackPreview = stripFences(raw).slice(0, 3500);
  aiAnalysisHtml = `<pre>${escapeHtml(fallbackPreview)}</pre>`;
  if (!parseError) {
    parseError = 'missing_ai_analysis_html_recovered';
    parseDetails = { recovered_from_raw_preview: true };
  }
}

if (!parsedConstructionYear || parsedConstructionYear <= 0) {
  parsedConstructionYear = Math.round(
    inferConstructionYearFromHtml($json.raw_md) ??
      inferConstructionYearFromHtml(aiAnalysisHtml) ??
      parsedConstructionYear
  );
}

parsedLotSize = normalizeLotSizeSqm(parsedLotSize, [$json.raw_md, aiAnalysisHtml, raw]);

const fallbackTitle = String($json.title || '').trim();
const shouldReplaceGenericTitle = !parsedTitle || /^Oferta:\s/i.test(parsedTitle);
const analysisText = stripTags(aiAnalysisHtml);
const titleFromAnalysis = analysisText.match(/Lokalizacja:\s*([^\.]+)\./i)?.[1]?.trim() || '';

return [{
  json: {
    ...$json,
    ai_parse_valid: parseError ? false : true,
    ai_parse_error: parseError,
    ai_parse_details: parseDetails,
    ai_parsed: {
      external_id: parsedExternalId,
      title: (shouldReplaceGenericTitle ? titleFromAnalysis : parsedTitle) || parsedTitle || fallbackTitle || 'Oferta: ' + parsedExternalId,
      price: parsedPrice,
      price_per_m2: parsedPricePerM2,
      area: parsedArea,
      lot_size: parsedLotSize,
      construction_year: parsedConstructionYear,
      ai_rating: roundedRating,
      ai_analysis_html: aiAnalysisHtml,
    },
  },
}];

const items = $input.all();

return items.filter((item) => {
  const externalId = String(item.json?.ai_parsed?.external_id || item.json?.external_id || '').trim();
  const aiRating = Number(item.json?.ai_parsed?.ai_rating);

  if (!externalId) {
    return false;
  }

  if (!Number.isFinite(aiRating) || aiRating < 1 || aiRating > 10) {
    return false;
  }

  return true;
});

const items = $input.all();

if (items.length === 0) {
  return [];
}

const runId = items[0]?.json?.run_id;

// Skip if no run_id (FK constraint violation)
if (!runId || String(runId).trim() === '' || String(runId).toLowerCase() === 'undefined') {
  return [];
}

// Count by event type
const counts = {
  passed: 0,
  dropped: 0,
};

// Count drops by reason
const dropsByReason = {};

for (const item of items) {
  const eventType = item.json.event_type;
  const reason = item.json.event_reason;

  if (eventType === 'passed') {
    counts.passed++;
  } else if (eventType === 'dropped') {
    counts.dropped++;
    dropsByReason[reason] = (dropsByReason[reason] || 0) + 1;
  }
}

const inputCount = counts.passed + counts.dropped;
const outputCount = counts.passed;
const droppedCount = counts.dropped;

return [{
  json: {
    run_id: runId,
    stage_key: 'validate_before_sql',
    stage_order: 4,
    input_count: inputCount,
    output_count: outputCount,
    dropped_count: droppedCount,
    metadata: {
      drops: dropsByReason
    }
  }
}];

const items = $input.all();

const normalizedIds = items
  .map((item) => String(item.json.external_id ?? '').trim())
  .filter((id) => id !== '' && id.toLowerCase() !== 'undefined');

const externalIds = Array.from(new Set(normalizedIds));

return [{
  json: {
    run_id: items[0]?.json?.run_id,
    external_ids: externalIds,
  }
}];

const sqlRows = $input.all();
const validItems = $('js-validate-offer-before-sql').all();

let existingIdsRaw = [];

if (sqlRows.length > 0) {
  const first = sqlRows[0]?.json?.existing_ids;
  if (Array.isArray(first)) {
    existingIdsRaw = first;
  } else if (typeof first === 'string' && first.trim() !== '') {
    try {
      const parsed = JSON.parse(first);
      if (Array.isArray(parsed)) {
        existingIdsRaw = parsed;
      }
    } catch (_) {
      existingIdsRaw = [];
    }
  }
}

const existing = new Set(existingIdsRaw.map((id) => String(id ?? '').trim()));

return validItems.map((item) => {
  const externalId = String(item.json.external_id ?? '').trim();

  return {
    ...item,
    json: {
      ...item.json,
      is_new_offer: externalId !== '' && !existing.has(externalId),
    },
  };
});

const upsertedItems = $input.all();
const taggedItems = $('tlm-tag-is-new').all();

const contextsByExternalId = new Map();
for (const item of taggedItems) {
  const externalId = String(item.json.external_id ?? '').trim();
  if (!contextsByExternalId.has(externalId)) {
    contextsByExternalId.set(externalId, []);
  }
  contextsByExternalId.get(externalId).push(item.json);
}

const takeContext = (externalId, fallbackIndex) => {
  const queue = contextsByExternalId.get(externalId);
  if (queue && queue.length > 0) {
    return queue.shift();
  }
  return taggedItems[fallbackIndex]?.json ?? {};
};

return upsertedItems.map((item, index) => {
  const externalId = String(item.json.external_id ?? '').trim();
  const context = takeContext(externalId, index);
  const isNew = Boolean(context.is_new_offer);

  return {
    json: {
      run_id: context.run_id,
      stage_key: 'upsert_offer',
      stage_order: 5,
      external_id: externalId,
      url: context.url || item.json.url || null,
      event_type: isNew ? 'inserted' : 'updated',
      event_reason: isNew ? 'new' : 'existing',
      payload: JSON.stringify({ is_new_offer: isNew }),
    },
  };
});

const items = $input.all();

if (items.length === 0) {
  return [];
}

const runId = items[0]?.json?.run_id;
if (!runId || String(runId).trim() === '' || String(runId).toLowerCase() === 'undefined') {
  return [];
}

let inserted = 0;
let updated = 0;

for (const item of items) {
  if (item.json.event_type === 'inserted') {
    inserted += 1;
  } else if (item.json.event_type === 'updated') {
    updated += 1;
  }
}

const outputCount = inserted + updated;

return [{
  json: {
    run_id: runId,
    stage_key: 'upsert_offer',
    stage_order: 5,
    input_count: outputCount,
    output_count: outputCount,
    dropped_count: 0,
    metadata: {
      inserted,
      updated,
    },
  },
}];

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '').slice(0, 15) + 'Z';
const random = Math.random().toString(36).slice(2, 14).toUpperCase();

return [{
  json: {
    run_id: `${timestamp}__${random}`,
    workflow_name: 'Real Estate AI Agent',
    workflow_version: '1.8.1',
    trigger_source: 'backfill',
    started_at: now.toISOString(),
  }
}];

const items = $input.all();

if (items.length === 0) {
  return [];
}

return items.map((item) => ({
  json: {
    run_id: item.json.run_id,
    stage_key: 'select_candidates',
    stage_order: 1,
    external_id: String(item.json.external_id || '').trim() || null,
    url: item.json.url || null,
    event_type: 'entered',
    event_reason: null,
    payload: {},
  },
}));

const items = $input.all();

if (items.length === 0) {
  return [];
}

const first = items[0]?.json || {};
const runId = String(first.run_id || '').trim();
const stageKey = String(first.stage_key || '').trim();
const stageOrder = Number(first.stage_order) || 0;

if (!runId || runId.toLowerCase() === 'undefined') {
  return [];
}
if (!stageKey) {
  return [];
}

const metadata = stageKey === 'update_offer_after_ai'
  ? { updated: items.length }
  : {};

return [{
  json: {
    run_id: runId,
    stage_key: stageKey,
    stage_order: stageOrder,
    input_count: items.length,
    output_count: items.length,
    dropped_count: 0,
    error_count: 0,
    metadata,
  },
}];

const items = $input.all();

const asNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? n : 0;
};

const extractTokenUsage = (item) => {
  const tokenPaths = [
    item.json?.usage,
    item.json?.tokenUsage,
    item.json?.responseMetadata?.tokenUsage,
    item.json?.output?.usage,
    item.json?.output?.tokenUsage,
    item.json?.raw?.usage,
  ];

  for (const usage of tokenPaths) {
    if (!usage || typeof usage !== 'object') continue;

    const inputTokens = asNumber(usage.input_tokens ?? usage.inputTokens ?? usage.prompt_tokens ?? usage.promptTokens ?? usage.input ?? usage.prompt);
    const outputTokens = asNumber(usage.output_tokens ?? usage.outputTokens ?? usage.completion_tokens ?? usage.completionTokens ?? usage.output ?? usage.completion);
    const totalTokens = asNumber(usage.total_tokens ?? usage.totalTokens ?? usage.total);

    if (inputTokens > 0 || outputTokens > 0 || totalTokens > 0) {
      const effectiveTotal = totalTokens > 0 ? totalTokens : inputTokens + outputTokens;
      return {
        input_tokens: inputTokens,
        output_tokens: outputTokens,
        total_tokens: effectiveTotal,
      };
    }
  }

  return null;
};

return items.map((item) => {
  const externalId = String(item.json?.ai_parsed?.external_id || item.json?.external_id || '').trim();
  const aiRating = Number(item.json?.ai_parsed?.ai_rating);
  const success = externalId !== '' && Number.isFinite(aiRating) && aiRating >= 1 && aiRating <= 10;
  const tokenUsage = extractTokenUsage(item);

  return {
    json: {
      run_id: item.json?.run_id || null,
      stage_key: 'ai_rate',
      stage_order: 4,
      external_id: externalId || null,
      url: item.json?.url || null,
      event_type: success ? 'rated' : 'failed',
      event_reason: success ? null : String(item.json?.ai_parse_error || 'invalid_ai_output'),
      payload: {
        ai_parse_valid: Boolean(item.json?.ai_parse_valid),
        ai_rating: success ? Math.round(aiRating) : null,
        ai: tokenUsage,
      },
    },
  };
}).filter((item) => String(item.json.external_id || '').trim() !== '');

const items = $input.all();

if (items.length === 0) {
  return [];
}

const runId = items[0]?.json?.run_id;
if (!runId || String(runId).trim() === '' || String(runId).toLowerCase() === 'undefined') {
  return [];
}

let rated = 0;
let failed = 0;
const failures = {};

const tokens = {
  input_tokens: 0,
  output_tokens: 0,
  total_tokens: 0,
};

for (const item of items) {
  const usage = item.json?.payload?.ai || {};
  tokens.input_tokens += Number(usage.input_tokens) || 0;
  tokens.output_tokens += Number(usage.output_tokens) || 0;
  tokens.total_tokens += Number(usage.total_tokens) || 0;

  if (item.json.event_type === 'rated') {
    rated += 1;
    continue;
  }

  failed += 1;
  const reason = String(item.json.event_reason || 'invalid_ai_output');
  failures[reason] = (failures[reason] || 0) + 1;
}

return [{
  json: {
    run_id: runId,
    stage_key: 'ai_rate',
    stage_order: 4,
    input_count: items.length,
    output_count: rated,
    dropped_count: failed,
    error_count: failed,
    metadata: {
      drops: failures,
      ai: tokens,
    },
  },
}];

const updatedItems = $input.all();
const sourceItems = $('js-aia-require-complete-output').all();

const contextsByExternalId = new Map();
for (const item of sourceItems) {
  const externalId = String(item.json?.external_id || item.json?.ai_parsed?.external_id || '').trim();
  if (!contextsByExternalId.has(externalId)) {
    contextsByExternalId.set(externalId, []);
  }
  contextsByExternalId.get(externalId).push(item.json);
}

const takeContext = (externalId, fallbackIndex) => {
  const queue = contextsByExternalId.get(externalId);
  if (queue && queue.length > 0) {
    return queue.shift();
  }
  return sourceItems[fallbackIndex]?.json ?? {};
};

return updatedItems.map((item, index) => {
  const externalId = String(item.json?.external_id || '').trim();
  const context = takeContext(externalId, index);
  const aiRating = Number(context?.ai_parsed?.ai_rating);
  const runId = String(context.run_id || '').trim();

  return {
    json: {
      run_id: runId || null,
      stage_key: 'update_offer_after_ai',
      stage_order: 5,
      external_id: externalId || String(context.external_id || '').trim() || null,
      url: context.url || item.json?.url || null,
      event_type: 'updated',
      event_reason: 'ai_rated',
      payload: {
        is_new_offer: false,
        ai_rating: Number.isFinite(aiRating) ? Math.round(aiRating) : null,
      },
    },
  };
}).filter((item) => String(item.json.run_id || '').trim() !== '' && String(item.json.external_id || '').trim() !== '');
